    {
        "kpi": " Business Unit with Missing Company",
        "description": "Associating business units with companies ensures hierarchical clarity, supports organizational alignment, and enables accurate company-level reporting.",
        "recommendation": "Ensure company field is filled during record creation and validate data periodically.",
        "table": "business_unit",
        "field": "companyISEMPTY"
    },
    {
        "kpi": "Business Units Without Business Head",
        "description": "Designating heads for business units establishes accountability, streamlines decision-making, and strengthens communication within the organization.",
        "recommendation": "Assign a responsible person to each BU and validate records regularly to ensure completeness.",
        "table": "business_unit",
        "field": "bu_headISEMPTY"
    },
    {
        "kpi": "Business Unit with Duplicate Records",
